def transform(wb):
    ws = wb['Sheet1']
    pattern = r'^[A-Z]+ *\d+(?:\.\d+)?$'
    for row in range(14, 138):
        cell = ws.cell(row=row, column=2)
        value = cell.value
        if value is not None:
            text = str(value)
            match = re.match(pattern, text)
            if match is not None:
                cell.value = re.sub(r'^[A-Z]+ *', '', text)
